+describe('isResponsesReasoningSignature', () => {
+  const replayPayload = JSON.stringify({
+    id: 'rs_68c6c0c9ff5c8191a29b2e78c1a40c83',
+    encrypted_content: 'gAAAAABvcmVhc29uaW5nLXJlcGxheS1wYXlsb2Fk',
